/**
 * Build a fixture `.torrent` file using the mature library. The fixture
 * is committed once (regenerated by `bun run scripts/build-fixtures.mjs`
 * when the test data changes) — it carries a real BEP-3 info dictionary
 * with piece hashes, so tests exercise the mature library's parsing
 * against the same shape a real swarm would produce.
 *
 * The fixture is INTENTIONALLY synthetic: a small mp4-named file with
 * deterministic piece bytes (no real media content — tests verify the
 * ENGINE's behavior, not media decoding). The infohash is stable for
 * the same inputs (regeneration is deterministic).
 */

import { writeFileSync, mkdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { toTorrentFile } from "parse-torrent";
import parseTorrent from "parse-torrent";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const fixturesDir = resolve(__dirname, "../tests/fixtures");

// --- the fixture's geometry --------------------------------------------------

const PIECE_LENGTH = 16 * 1024; // 16 KiB — small pieces for compact fixtures
const FILE_BYTES = PIECE_LENGTH * 4; // 64 KiB total — 4 pieces
const FILE_NAME = "sintel-trailer.mp4";
const FILE_BYTES_CONTENT = Buffer.alloc(FILE_BYTES, 0);
// Fill with deterministic content that is unique per piece (so each piece
// has a different SHA-1 hash, matching real swarm behavior). The content
// is a ramp that crosses piece boundaries, so each piece sees a different
// 16 KiB window of the ramp.
for (let i = 0; i < FILE_BYTES; i += 1) {
  FILE_BYTES_CONTENT[i] = (i + (i >> 8) * 13 + 7) & 0xff;
}

// --- compute the piece hashes (BEP-3) ----------------------------------------

const pieceHashes = [];
for (let i = 0; i < 4; i += 1) {
  const slice = FILE_BYTES_CONTENT.subarray(i * PIECE_LENGTH, (i + 1) * PIECE_LENGTH);
  pieceHashes.push(createHash("sha1").update(slice).digest());
}
const piecesBuf = Buffer.concat(pieceHashes);

// --- build the info dictionary (BEP-3 v1 single-file torrent) ----------------

const info = {
  name: FILE_NAME,
  "piece length": PIECE_LENGTH,
  pieces: piecesBuf,
  length: FILE_BYTES,
};

const torrent = {
  info,
  announce: ["udp://tracker.example:1337"],
  "creation date": 1700000000,
  "created by": "wfx-r11-test-fixture",
};

const buf = toTorrentFile(torrent);

mkdirSync(fixturesDir, { recursive: true });
writeFileSync(join(fixturesDir, "sintel-single.torrent"), buf);

// --- also write the magnet URI ----------------------------------------------

const parsed = await parseTorrent(buf);
const infoHash = parsed.infoHash;
const magnet = `magnet:?xt=urn:btih:${infoHash}&dn=${encodeURIComponent(FILE_NAME)}&tr=${encodeURIComponent("udp://tracker.example:1337")}`;
writeFileSync(join(fixturesDir, "sintel-single.magnet.txt"), magnet + "\n", "utf8");

// --- write the fixture bytes (the loopback's data backing) -------------------

writeFileSync(join(fixturesDir, "sintel-single.bin"), FILE_BYTES_CONTENT);

// --- write the metadata summary (the expected piece geometry) ----------------

const summary = {
  infoHash,
  name: FILE_NAME,
  pieceLength: PIECE_LENGTH,
  pieceCount: 4,
  totalBytes: FILE_BYTES,
  files: [{ path: FILE_NAME, lengthBytes: FILE_BYTES, playableHint: true }],
  pieceSha1Hex: pieceHashes.map((p) => p.toString("hex")),
};
writeFileSync(join(fixturesDir, "sintel-single.summary.json"), JSON.stringify(summary, null, 2));

console.log(`fixture built: infoHash=${infoHash}`);
console.log(`  .torrent: ${buf.byteLength} bytes`);
console.log(`  magnet:   ${magnet.length} chars`);
console.log(`  bin:      ${FILE_BYTES} bytes (${PIECE_LENGTH} * 4 pieces)`);
